-- Apologetics additions — run after apologetics.sql
-- Adds 13 new arguments across all three categories.

-- ============================================================
-- EXISTENCE OF GOD — 6 new arguments (orders 6–11)
-- ============================================================

INSERT INTO apologetics_arguments
  (id, category, order_in_category, title_en, title_pt, subtitle_en, subtitle_pt,
   logical_form_en, logical_form_pt, explanation_en, explanation_pt, historical_origin)
VALUES

('teleological', 'existence_of_god', 6,
 'The Teleological Argument',
 'O Argumento Teleológico',
 'The order and design of the universe point to an intelligent designer.',
 'A ordem e o design do universo apontam para um designer inteligente.',
 '{"premises": ["Everything that exhibits complex, ordered design was produced by an intelligent mind.", "The universe exhibits complex, ordered design."], "conclusion": "Therefore, the universe was produced by an intelligent mind."}',
 '{"premises": ["Tudo o que exibe design complexo e ordenado foi produzido por uma mente inteligente.", "O universo exibe design complexo e ordenado."], "conclusion": "Logo, o universo foi produzido por uma mente inteligente."}',
 'The teleological argument — from the Greek telos, meaning "end" or "purpose" — observes that the natural world displays unmistakable features of intentional design: orderly laws, consistent mathematical structure, and entities whose parts work together toward specific functions. When we observe a watch, we infer a watchmaker not because we saw it being made, but because the complexity and coordination of its parts are precisely the kind of effect that minds, not random processes, produce. The same reasoning applies at every scale of nature: from the atomic bonds that hold matter together to the biochemical machinery of living cells to the large-scale structure of the cosmos. Everywhere in nature we find precisely the kind of functional, specified complexity that in every other context we recognize as the signature of a designing intelligence. A table, a car, a door — even the simplest artefact signals its maker because its parts are coordinated toward an end. The universe is incomparably more ordered than any artefact. The most coherent explanation for the universe exhibiting this kind of structure — rather than being a structureless chaos — is that it was designed by a rational mind.',
 'O argumento teleológico — do grego telos, que significa "fim" ou "propósito" — observa que o mundo natural exibe características inconfundíveis de design intencional: leis ordenadas, estrutura matemática consistente e entidades cujas partes funcionam em conjunto para fins específicos. Quando observamos um relógio, inferimos um relojoeiro não porque o vimos ser fabricado, mas porque a complexidade e coordenação das suas partes são precisamente o tipo de efeito que as mentes, e não os processos aleatórios, produzem. O mesmo raciocínio aplica-se a todas as escalas da natureza: desde as ligações atómicas que mantêm a matéria unida até à maquinaria bioquímica das células vivas e à estrutura em grande escala do cosmos. Em toda a natureza encontramos precisamente o tipo de complexidade funcional e especificada que em qualquer outro contexto reconhecemos como a marca de uma inteligência criadora. Uma mesa, um carro, uma porta — mesmo o artefacto mais simples sinaliza o seu criador porque as suas partes estão coordenadas para um fim. O universo é incomparavelmente mais ordenado do que qualquer artefacto. A explicação mais coerente para o universo exibir este tipo de estrutura — em vez de ser um caos sem forma — é que foi desenhado por uma mente racional.',
 'Plato, Timaeus (c. 360 BC); Aristotle, Physics (c. 350 BC); Thomas Aquinas, Summa Theologiae, Fifth Way (c. 1265–1274); William Paley, Natural Theology (1802).'),

('irreducible_complexity', 'existence_of_god', 7,
 'Irreducible Complexity',
 'Complexidade Irredutível',
 'Many biological systems cannot function if any single component is removed — they could not have been assembled step by step.',
 'Muitos sistemas biológicos não funcionam se qualquer componente for removido — não poderiam ter sido montados passo a passo.',
 NULL, NULL,
 'Some biological systems consist of multiple interacting parts, each of which is necessary for the whole to function at all. Remove any single part and the system fails completely — there is no partially functional intermediate state that natural selection could favour at each step. The human eye illustrates this clearly: the retina, the lens, the cornea, the optic nerve, and the biochemical pathway that converts light into neural signals must all be present and properly coordinated for the eye to produce vision. A retina without a lens produces no image; a lens without a retina produces no perception. A light-sensitive spot without the neural architecture to interpret signals is useless. The incremental, step-by-step process of undirected evolution struggles to account for systems where each component has no survival value until every other component is already in place. This is not an argument from ignorance — it is an argument from the observed pattern that specified, integrated complexity of this kind, in every other domain of experience, is reliably the product of intelligent foresight. An engineer who designs a system can envision the completed whole before assembling the parts; an unguided process cannot.',
 'Alguns sistemas biológicos consistem em múltiplos componentes em interação, cada um dos quais é necessário para que o conjunto funcione. Remova qualquer peça e o sistema falha completamente — não existe estado intermédio parcialmente funcional que a seleção natural pudesse favorecer passo a passo. O olho humano ilustra isto claramente: a retina, o cristalino, a córnea, o nervo ótico e a via bioquímica que converte a luz em sinais neurais devem estar todos presentes e devidamente coordenados para que o olho produza visão. Uma retina sem cristalino não produz imagem; um cristalino sem retina não produz perceção. Um ponto fotossensível sem a arquitetura neural para interpretar os sinais é inútil. O processo incremental e gradual da evolução não orientada tem dificuldade em explicar sistemas em que cada componente não tem valor de sobrevivência enquanto todos os outros não estiverem já no lugar. Este não é um argumento da ignorância — é um argumento a partir do padrão observado de que a complexidade integrada e especificada deste tipo, em todos os outros domínios da experiência, é de forma fiável produto da previsão inteligente. Um engenheiro que projeta um sistema pode antecipar o todo completo antes de montar as peças; um processo não orientado não pode.',
 'William Paley, Natural Theology (1802); Michael Behe, Darwin''s Black Box (1996).'),

('dna_information', 'existence_of_god', 8,
 'The Argument from Biological Information',
 'O Argumento da Informação Biológica',
 'The information encoded in DNA presupposes an intelligent source.',
 'A informação codificada no DNA pressupõe uma fonte inteligente.',
 '{"premises": ["Wherever we observe large quantities of specified, functional information, the cause is always a mind.", "DNA contains vast quantities of specified, functional information — approximately 3.2 billion base pairs encoding the construction of a living organism."], "conclusion": "Therefore, the most plausible cause of the information in DNA is a mind."}',
 '{"premises": ["Onde quer que observemos grandes quantidades de informação especificada e funcional, a causa é sempre uma mente.", "O DNA contém vastas quantidades de informação especificada e funcional — aproximadamente 3,2 mil milhões de pares de bases que codificam a construção de um organismo vivo."], "conclusion": "Logo, a causa mais plausível da informação no DNA é uma mente."}',
 'Information is a non-material reality: it is not itself matter or energy, but it is reliably produced by minds and never, in any observed case, by unguided physical processes alone. A sentence found in a bowl of alphabet soup is immediately recognizable as the product of a mind, not of random motion, because it exhibits specified complexity — characters arranged in a functional sequence according to a pre-existing code. Human DNA encodes approximately 3.2 billion base pairs, and each base (adenine, thymine, cytosine, or guanine) functions like a letter in a four-character alphabet. The sequence of these bases specifies — with extraordinary precision — the structure of every protein in the human body, governing everything from eye colour to the folding of enzymes. This is not mere chemical regularity, like the repeating pattern of a crystal, but genuine information: a highly specific, non-repetitive sequence that carries functional meaning relative to an independently existing code (the genetic code). Every instance of such specified, functional information in human experience originates from a mind. The information content of a single human cell vastly exceeds that of the largest human libraries. The most coherent explanation for its origin is an intelligent source.',
 'A informação é uma realidade não-material: não é ela própria matéria nem energia, mas é produzida de forma fiável por mentes e nunca, em nenhum caso observado, por processos físicos não orientados. Uma frase encontrada numa taça de sopa de letras é imediatamente reconhecida como produto de uma mente, e não de movimento aleatório, porque exibe complexidade especificada — caracteres dispostos numa sequência funcional de acordo com um código pré-existente. O DNA humano codifica aproximadamente 3,2 mil milhões de pares de bases, e cada base (adenina, timina, citosina ou guanina) funciona como uma letra num alfabeto de quatro caracteres. A sequência dessas bases especifica — com precisão extraordinária — a estrutura de cada proteína do corpo humano, regulando tudo, desde a cor dos olhos até ao dobramento das enzimas. Não se trata de mera regularidade química, como o padrão repetitivo de um cristal, mas de informação genuína: uma sequência altamente específica e não repetitiva que transporta significado funcional relativamente a um código pré-existente independente (o código genético). Cada instância de informação funcional especificada na experiência humana tem origem numa mente. O conteúdo informacional de uma única célula humana excede em muito o das maiores bibliotecas humanas. A explicação mais coerente para a sua origem é uma fonte inteligente.',
 'Francis Crick and James Watson, DNA structure (1953); developed philosophically by Antony Flew, There Is a God (2007); Stephen Meyer, Signature in the Cell (2009).'),

('argument_from_reason', 'existence_of_god', 9,
 'The Argument from Reason',
 'O Argumento da Razão',
 'Rationality cannot be the product of irrational, unguided physical processes.',
 'A racionalidade não pode ser produto de processos físicos irracionais e não orientados.',
 '{"premises": ["If naturalism is true, all mental events — including beliefs — are produced entirely by non-rational physical causes.", "Beliefs produced entirely by non-rational causes cannot be trusted as reliable guides to truth.", "We do trust our rational faculties as reliable guides to truth — including when we reason about naturalism itself."], "conclusion": "Therefore, if naturalism is true, we have no reason to trust our belief that naturalism is true — naturalism is self-defeating."}',
 '{"premises": ["Se o naturalismo é verdadeiro, todos os eventos mentais — incluindo as crenças — são produzidos inteiramente por causas físicas não-racionais.", "Crenças produzidas inteiramente por causas não-racionais não podem ser consideradas guias fiáveis para a verdade.", "Confiamos nas nossas faculdades racionais como guias fiáveis para a verdade — incluindo quando raciocinamos sobre o próprio naturalismo."], "conclusion": "Logo, se o naturalismo é verdadeiro, não temos razão para confiar na crença de que o naturalismo é verdadeiro — o naturalismo é autoderrotante."}',
 'The argument from reason observes a deep tension within materialism. If the human mind is nothing more than the product of unguided, non-rational physical processes — neurons firing in patterns shaped by chemistry and the pressures of natural selection — then our beliefs are simply the outputs of those physical processes. Evolution selects for survival value, not truth-tracking: a brain shaped to produce behaviours that maximize reproductive fitness has no guarantee of producing true beliefs; it merely produces useful ones. But if we cannot trust our rational faculties to reliably distinguish truth from falsehood, then we cannot trust the reasoning that leads us to accept materialism in the first place. The position is self-defeating: to reason your way to the conclusion that reason is unreliable is to saw off the branch on which you are sitting. Rationality — the capacity to recognize logical entailments, weigh evidence, follow an argument to its conclusion regardless of its survival value — is precisely the kind of non-physical, truth-directed reality that a theistic worldview expects but that materialism cannot coherently account for. On theism, human rationality reflects the image of a rational Creator; on materialism, it is an accidental by-product of blind selection pressure, with no guarantee of accuracy.',
 'O argumento da razão observa uma tensão profunda no interior do materialismo. Se a mente humana é apenas o produto de processos físicos não orientados e não racionais — neurónios a disparar em padrões moldados pela química e pelas pressões da seleção natural — então as nossas crenças são simplesmente os resultados desses processos físicos. A evolução seleciona pelo valor de sobrevivência, não pela capacidade de atingir a verdade: um cérebro moldado para produzir comportamentos que maximizam a aptidão reprodutiva não tem garantia de produzir crenças verdadeiras; produz apenas crenças úteis. Mas se não podemos confiar nas nossas faculdades racionais para distinguir de forma fiável a verdade da falsidade, então não podemos confiar no raciocínio que nos leva a aceitar o materialismo. A posição é autoderrotante: raciocinar até à conclusão de que a razão é pouco fiável é serrar o ramo em que se está sentado. A racionalidade — a capacidade de reconhecer implicações lógicas, pesar evidências, seguir um argumento até à sua conclusão independentemente do seu valor de sobrevivência — é precisamente o tipo de realidade não-física e orientada para a verdade que uma visão do mundo teísta espera, mas que o materialismo não consegue explicar de forma coerente. No teísmo, a racionalidade humana reflete a imagem de um Criador racional; no materialismo, é um subproduto acidental de pressão de seleção cega, sem garantia de precisão.',
 'C.S. Lewis, Miracles (1947), Chapter 3; Alvin Plantinga, Evolutionary Argument Against Naturalism (1993).'),

('argument_from_life', 'existence_of_god', 10,
 'The Argument from Abiogenesis',
 'O Argumento da Abiogénese',
 'The origin of life from non-living matter has never been observed and presents a profound explanatory challenge for naturalism.',
 'A origem da vida a partir de matéria não-viva nunca foi observada e apresenta um desafio explicativo profundo para o naturalismo.',
 NULL, NULL,
 'Throughout the entire history of scientific observation, life has only ever been observed to arise from pre-existing life. Louis Pasteur''s decisive experiments in 1859 refuted spontaneous generation — the idea that life arises spontaneously from non-living matter — and no subsequent experiment has reversed this finding. The simplest known self-replicating organism requires hundreds of proteins, each precisely specified by genetic information, and the genetic information itself requires pre-existing proteins to be read and copied. This circularity — proteins need DNA to be made, DNA needs proteins to be read — makes a purely chemical origin of life extraordinarily difficult to account for. Beyond the circularity, the probability of assembling even a single short functional protein by chance from a pool of amino acids is extraordinarily unfavourable: the amino acids must be the correct type, in the correct sequence, and in the correct spatial orientation. The French probabilist Émile Borel proposed that any probability below one in 10⁵⁰ can be treated as a physical impossibility — no such event could occur even once across all the atoms of the universe in all of cosmic time. The spontaneous assembly of a first living cell — requiring not one but hundreds of precisely specified proteins, a functional genetic code, a membrane, and an integrated metabolic system — falls far beyond that threshold by many orders of magnitude. The existence of biological life calls for an explanation that naturalism has not provided.',
 'Ao longo de toda a história da observação científica, a vida só foi observada a surgir de vida pré-existente. As experiências decisivas de Louis Pasteur em 1859 refutaram a geração espontânea — a ideia de que a vida surge espontaneamente de matéria não-viva — e nenhuma experiência posterior inverteu esta conclusão. O organismo auto-replicante mais simples conhecido requer centenas de proteínas, cada uma especificada com precisão por informação genética, e a própria informação genética requer proteínas pré-existentes para ser lida e copiada. Esta circularidade — as proteínas precisam de DNA para serem produzidas, o DNA precisa de proteínas para ser lido — torna uma origem puramente química da vida extraordinariamente difícil de explicar. Para além da circularidade, a probabilidade de montar uma única proteína funcional curta por acaso a partir de um reservatório de aminoácidos é extraordinariamente desfavorável: os aminoácidos devem ser do tipo correto, na sequência correta e na orientação espacial correta. O probabilista francês Émile Borel propôs que qualquer probabilidade inferior a um em 10⁵⁰ pode ser tratada como uma impossibilidade física — tal evento não poderia ocorrer nem uma vez em todos os átomos do universo em todo o tempo cósmico. A montagem espontânea de uma primeira célula viva — exigindo não uma, mas centenas de proteínas especificadas com precisão, um código genético funcional, uma membrana e um sistema metabólico integrado — fica muito além desse limiar por muitas ordens de grandeza. A existência de vida biológica exige uma explicação que o naturalismo não forneceu.',
 'Louis Pasteur, refutation of spontaneous generation (1859); Émile Borel, probability threshold (1913); Antony Flew, There Is a God (2007).'),

('argument_from_love', 'existence_of_god', 11,
 'The Argument from Immaterial Experience',
 'O Argumento da Experiência Imaterial',
 'Experiences like love and self-sacrifice cannot be fully reduced to physical or evolutionary processes.',
 'Experiências como o amor e o autossacrifício não podem ser plenamente reduzidas a processos físicos ou evolutivos.',
 NULL, NULL,
 'Within a strictly materialist framework, all mental and emotional states must be reducible to electrochemical processes in the brain: the firing of neurons, the release of neurotransmitters, the operation of systems shaped by evolutionary selection for reproductive fitness. On this view, love is a biochemical response that promotes pair-bonding and offspring protection — selected because it enhances survival, no more intrinsically meaningful than a pain reflex. Yet human experience persistently resists this reduction. People routinely love in ways that carry no reproductive advantage: parents sacrifice careers and health for terminally ill children with no prospect of passing on genes; strangers give their lives for people they have never met; people choose forgiveness, celibacy, or voluntary poverty — not as survival strategies, but as free responses to the genuine worth of another person. These acts are not merely feelings; they are chosen, costly, and oriented toward a good that transcends biological self-interest entirely. Moreover, love is not always accompanied by the biochemical "feelings" of attraction or warmth — parents continue to love children who cause them only pain; spouses love through illness and decline. If love were only chemistry, it would track the chemistry. That it does not — that love persists as a free commitment independent of emotional reward — points to something that exceeds the physical. Theism offers a coherent grounding: a personal God who is love (1 John 4:8) created personal beings capable of participating in that love across conditions that no evolutionary mechanism could predict or require.',
 'Num quadro estritamente materialista, todos os estados mentais e emocionais devem ser redutíveis a processos eletroquímicos no cérebro: o disparo de neurónios, a libertação de neurotransmissores, o funcionamento de sistemas moldados pela seleção evolutiva para a aptidão reprodutiva. Nesta perspetiva, o amor é uma resposta bioquímica que promove a ligação de pares e a proteção da descendência — selecionada porque aumenta a sobrevivência, não mais intrinsecamente significativa do que um reflexo de dor. No entanto, a experiência humana resiste persistentemente a esta redução. As pessoas amam rotineiramente de formas que não têm qualquer vantagem reprodutiva: pais sacrificam carreiras e saúde por filhos com doenças terminais sem perspetiva de transmissão genética; estranhos dão a vida por pessoas que nunca conheceram; as pessoas escolhem o perdão, o celibato ou a pobreza voluntária — não como estratégias de sobrevivência, mas como respostas livres ao valor genuíno de outra pessoa. Estes atos não são meros sentimentos; são escolhidos, dispendiosos e orientados para um bem que transcende inteiramente o interesse biológico próprio. Além disso, o amor nem sempre é acompanhado pelos "sentimentos" bioquímicos de atração ou calor — os pais continuam a amar filhos que lhes causam apenas sofrimento; os cônjuges amam através da doença e do declínio. Se o amor fosse apenas química, seguiria a química. O facto de não o fazer — de o amor persistir como um compromisso livre independente da recompensa emocional — aponta para algo que excede o físico. O teísmo oferece um fundamento coerente: um Deus pessoal que é amor (1 João 4:8) criou seres pessoais capazes de participar nesse amor em condições que nenhum mecanismo evolutivo poderia prever ou exigir.',
 'C.S. Lewis, The Four Loves (1960); developed in contemporary philosophy by J.P. Moreland and Dallas Willard.');

-- ============================================================
-- GOSPEL RELIABILITY — 3 new arguments (orders 6–8)
-- ============================================================

INSERT INTO apologetics_arguments
  (id, category, order_in_category, title_en, title_pt, subtitle_en, subtitle_pt,
   logical_form_en, logical_form_pt, explanation_en, explanation_pt, historical_origin)
VALUES

('manuscript_evidence', 'gospel_reliability', 6,
 'Manuscript Evidence',
 'Evidência Manuscrita',
 'The New Testament is by far the best-attested document of the ancient world.',
 'O Novo Testamento é de longe o documento mais atestado do mundo antigo.',
 NULL, NULL,
 'Historical documents are evaluated in part by the number of surviving manuscript copies and by the gap between the original composition and the earliest surviving copy — the shorter the gap and the greater the number of copies, the more confidence we can have that the text we possess reflects what the original authors wrote. By both criteria, the New Testament stands in a class of its own among ancient texts. There are over 5,700 Greek manuscript copies of the New Testament, in whole or in part, plus over 10,000 Latin manuscripts and thousands more in other early languages — a total manuscript base exceeding 24,000 copies. The textual agreement between these manuscripts is approximately 99.5%; the remaining 0.5% consists entirely of minor variations — spelling differences, word order, and similar — that do not affect any historical claim or point of doctrine. The earliest New Testament fragment (Papyrus P52, a portion of John''s Gospel) dates to within 25–50 years of the original composition. For comparison: Caesar''s Gallic Wars survives in about 10 manuscripts, the oldest of which dates to roughly 900 years after Caesar wrote it; Aristotle''s works survive in approximately 49 manuscripts, the oldest about 1,400 years after Aristotle. No scholar doubts the existence of Caesar or Aristotle on the basis of manuscript evidence. The same standards of historical credibility that lead scholars to accept those texts require them — by consistency — to accept that the New Testament text reliably transmits what its original authors wrote.',
 'Os documentos históricos são avaliados em parte pelo número de cópias manuscritas sobreviventes e pelo intervalo entre a composição original e a cópia sobrevivente mais antiga — quanto mais curto o intervalo e maior o número de cópias, maior a confiança de que o texto que possuímos reflete o que os autores originais escreveram. Por ambos os critérios, o Novo Testamento está numa categoria própria entre os textos antigos. Existem mais de 5.700 cópias de manuscritos gregos do Novo Testamento, na totalidade ou em parte, mais de 10.000 manuscritos latinos e milhares mais noutras línguas antigas — uma base de manuscritos total que excede os 24.000. O acordo textual entre esses manuscritos é de aproximadamente 99,5%; os restantes 0,5% consistem inteiramente em variações menores — diferenças ortográficas, ordem das palavras e similares — que não afetam nenhuma afirmação histórica ou ponto de doutrina. O fragmento mais antigo do Novo Testamento (Papiro P52, uma porção do Evangelho de João) data de 25 a 50 anos após a composição original. Em comparação: a Guerra das Gálias de César sobrevive em cerca de 10 manuscritos, o mais antigo dos quais data de aproximadamente 900 anos depois de César o ter escrito; as obras de Aristóteles sobrevivem em aproximadamente 49 manuscritos, o mais antigo cerca de 1.400 anos depois de Aristóteles. Nenhum historiador duvida da existência de César ou Aristóteles com base na evidência manuscrita. Os mesmos padrões de credibilidade histórica que levam os historiadores a aceitar esses textos exigem-lhes — por coerência — aceitar que o texto do Novo Testamento transmite de forma fiável o que os seus autores originais escreveram.',
 'F.F. Bruce, The New Testament Documents: Are They Reliable? (1943); John Warwick Montgomery, History, Law and Christianity (1964); Kurt Aland and Barbara Aland, The Text of the New Testament (1987).'),

('undesigned_coincidences', 'gospel_reliability', 7,
 'Undesigned Coincidences',
 'Coincidências Não Planeadas',
 'Details in one Gospel that only make sense alongside another — a mark of authentic independent testimony.',
 'Detalhes num Evangelho que só fazem sentido em paralelo com outro — uma marca de testemunho independente e autêntico.',
 NULL, NULL,
 'An undesigned coincidence is a detail in one account that appears incomplete or puzzling in isolation, but fits naturally with an incidental detail in a separate, independently written account — in a way that neither author appears to have planned or coordinated. These interlocking details are characteristic of genuine eyewitness accounts about the same events: real witnesses notice different aspects of the same scene, and their accounts mesh in ways they did not contrive. They would be extremely unlikely to appear if the accounts were either fabricated independently or derived from a single coordinated source. A clear example: John 6:5 records that Jesus asks Philip "Where shall we buy bread for these people?" but gives no explanation for why Philip was singled out. Luke 9:10 mentions, incidentally, that the feeding took place near Bethsaida — and John 1:44 records that Philip was from Bethsaida. The natural inference is that Jesus asked Philip because Philip was the local who would know where to buy food. Neither John nor Luke draws this connection; it only becomes visible when both accounts are read together. A second example: John 6:10 notes that "there was plenty of grass in the place." Matthew 14 and Mark 6 supply the context: the event occurred at Passover, in spring — explaining why grass would be abundant. John records the detail; the other Gospels explain it without knowing they do. These unplanned interlocks, consistent across multiple Gospel pairs, indicate that the authors were independently drawing on genuine memories of real events rather than constructing a coordinated narrative.',
 'Uma coincidência não planeada é um detalhe num relato que parece incompleto ou desconcertante de forma isolada, mas que se encaixa naturalmente com um detalhe incidental num relato separado e escrito de forma independente — de uma forma que nenhum dos autores parece ter planeado ou coordenado. Estes detalhes entrelaçados são característicos de testemunhos oculares genuínos sobre os mesmos eventos: testemunhas reais notam aspetos diferentes da mesma cena, e os seus relatos encaixam de formas que não combinaram. Seriam extremamente improváveis de aparecer se os relatos fossem fabricados de forma independente ou derivados de uma única fonte coordenada. Um exemplo claro: João 6:5 regista que Jesus pergunta a Filipe "Onde compraremos pão para esta gente?", mas não dá nenhuma explicação para a escolha de Filipe. Lucas 9:10 menciona, incidentalmente, que a multiplicação aconteceu perto de Betsaida — e João 1:44 regista que Filipe era de Betsaida. A inferência natural é que Jesus perguntou a Filipe porque Filipe era o local que saberia onde comprar comida. Nem João nem Lucas estabelecem esta ligação; ela só se torna visível quando ambos os relatos são lidos em conjunto. Um segundo exemplo: João 6:10 nota que "havia muita erva naquele lugar." Mateus 14 e Marcos 6 fornecem o contexto: o evento ocorreu na Páscoa, na primavera — explicando por que haveria erva abundante. João regista o detalhe; os outros Evangelhos explicam-no sem o saberem. Estes entrelaçamentos não planeados, consistentes em múltiplos pares de Evangelhos, indicam que os autores estavam a recorrer de forma independente a memórias genuínas de eventos reais, em vez de construírem uma narrativa coordenada.',
 'J.J. Blunt, Undesigned Coincidences in the Writings Both of the Old and New Testament (1847, public domain); Lydia McGrew, Hidden in Plain View (2017).'),

('luke_as_historian', 'gospel_reliability', 8,
 'Luke''s Historical Precision',
 'A Precisão Histórica de Lucas',
 'Luke writes with the methods of first-century historians — and every verifiable detail checks out.',
 'Lucas escreve com os métodos dos historiadores do século I — e todos os detalhes verificáveis conferem.',
 NULL, NULL,
 'Luke opens his Gospel with a formal historiographical preface (Luke 1:1–4) explicitly stating his methodology: careful investigation from the beginning, consultation of eyewitnesses, and the production of an orderly account. This is precisely the language of serious first-century historical writing — the same terminology and stated aims appear in Thucydides, Polybius, and Josephus. In his second volume, Acts, Luke names rulers, provinces, administrative titles, and local officials with extraordinary specificity. Critics once dismissed these details as errors, but archaeological and epigraphic discoveries have consistently vindicated Luke: the title "politarchs" for the magistrates of Thessalonica (Acts 17:6) — long called a Lukan invention — was confirmed by multiple inscriptions found in Macedonia; the title "protos" (first man) for the governor of Malta (Acts 28:7) was confirmed by Maltese inscriptions; the description of Gallio as "proconsul" of Achaia (Acts 18:12), rather than legate, was confirmed by the Delphi Inscription dated to 51–52 AD, which also fixes the chronology of Paul''s visit with unusual precision. Luke also correctly uses the word "Asiarchs" (Acts 19:31), a title with a specific technical meaning in the civic administration of Roman Asia. The archaeologist Sir William Ramsay, beginning his research as a skeptic, spent years attempting to disprove Luke''s historical accuracy and concluded that Luke is "a historian of the first rank." The same level of casual, unforced accuracy that characterizes Luke''s administrative and geographical details is precisely what we would expect from a careful historian drawing on contemporary sources and personal investigation — and precisely what we would not expect from a later fabricator.',
 'Lucas abre o seu Evangelho com um prefácio historiográfico formal (Lucas 1:1–4) que enuncia explicitamente a sua metodologia: investigação cuidadosa desde o início, consulta de testemunhas oculares e produção de um relato ordenado. Esta é precisamente a linguagem da escrita histórica séria do século I — a mesma terminologia e os mesmos objetivos declarados aparecem em Tucídides, Políbio e Josefo. No seu segundo volume, os Atos dos Apóstolos, Lucas nomeia governantes, províncias, títulos administrativos e funcionários locais com especificidade extraordinária. Os críticos outrora consideraram estes detalhes erros, mas as descobertas arqueológicas e epigráficas têm consistentemente vindicado Lucas: o título "politarcas" para os magistrados de Tessalónica (Atos 17:6) — considerado durante muito tempo uma invenção de Lucas — foi confirmado por múltiplas inscrições encontradas na Macedónia; o título "protos" (primeiro homem) para o governador de Malta (Atos 28:7) foi confirmado por inscrições maltesas; a descrição de Galio como "procônsul" da Acaia (Atos 18:12), em vez de legado, foi confirmada pela Inscrição de Delfos datada de 51–52 d.C., que também fixa com precisão incomum a cronologia da visita de Paulo. Lucas também utiliza corretamente a palavra "Asiarcas" (Atos 19:31), um título com um significado técnico específico na administração cívica da Ásia romana. O arqueólogo Sir William Ramsay, iniciando a sua investigação como cético, passou anos a tentar refutar a precisão histórica de Lucas e concluiu que Lucas é "um historiador de primeira ordem." O mesmo nível de precisão casual e sem esforço que caracteriza os detalhes administrativos e geográficos de Lucas é precisamente o que esperaríamos de um historiador cuidadoso a trabalhar a partir de fontes contemporâneas e investigação pessoal — e precisamente o que não esperaríamos de um fabricador posterior.',
 'Sir William Ramsay, St. Paul the Traveller and the Roman Citizen (1895, public domain); Colin Hemer, The Book of Acts in the Setting of Hellenistic History (1989); the Delphi Inscription (51–52 AD).');

